albums = FileAttachment("data/albums.csv").csv({ typed: true })

viewof selectedArtist = Inputs.select([...new Set(albums.map(d =&gt; d.artist))], {
  label: "Select an artist:"
})

filteredAlbums = albums.filter(d =&gt; d.artist === selectedArtist)

viewof selected = Inputs.select(filteredAlbums, {
  label: "Select an album:",
  format: d =&gt; `${d.title} (${d.year})`
})

html`&lt;div style="margin-top: 20px; margin-bottom: 30px;"&gt;
  &lt;img src="data/${selected?.cover_filename}" alt="${selected?.title}" style="max-width: 400px; width: 100%; border-radius: 8px; box-shadow: 0 4px 6px rgba(0,0,0,0.1);" onerror="this.style.display='none'; this.nextElementSibling.style.display='block';"&gt;
  &lt;p style="display:none; color: #888; font-style: italic;"&gt;Cover image not available.&lt;/p&gt;
&lt;/div&gt;`

Cover Color Similarity

similarity = FileAttachment("data/similarity.csv").csv({ typed: true })

selectedAlbumName = selected ? `${selected.title} (${selected.year})` : ""

matches = similarity
  .filter(d =&gt; d["Album 1"] === selectedAlbumName || d["Album 2"] === selectedAlbumName)
  .map(d =&gt; {
    const isFirst = d["Album 1"] === selectedAlbumName;
    const albumName = isFirst ? d["Album 2"] : d["Album 1"];
    const artistName = isFirst ? d["Artist 2"] : d["Artist 1"];
    const info = albums.find(a =&gt; `${a.title} (${a.year})` === albumName);
    return {
      album: albumName,
      artist: artistName,
      similarity: d["Similarity"],
      cover: info ? info.cover_filename : null
    };
  })
  .sort((a, b) =&gt; b.similarity - a.similarity)

mostSimilar = matches[0]
mostDifferent = matches[matches.length - 1]

html`
${!mostSimilar ? html`&lt;p style="color: #888; font-style: italic;"&gt;No similarity data available for this album.&lt;/p&gt;` : html`
&lt;div style="display: flex; gap: 30px; flex-wrap: wrap; margin-top: 15px;"&gt;
  &lt;div style="flex: 1; min-width: 220px; max-width: 300px; text-align: center;"&gt;
    &lt;h4 style="color: #2e7d32;"&gt;Most Similar (${mostSimilar.similarity}%)&lt;/h4&gt;
    &lt;img src="data/${mostSimilar.cover}" alt="${mostSimilar.album}" style="width: 100%; border-radius: 8px; box-shadow: 0 4px 6px rgba(0,0,0,0.1);"&gt;
    &lt;p style="margin-top: 8px; font-weight: bold; margin-bottom: 2px;"&gt;${mostSimilar.album}&lt;/p&gt;
    &lt;p style="color: #666; margin-top: 0;"&gt;${mostSimilar.artist}&lt;/p&gt;
  &lt;/div&gt;
  &lt;div style="flex: 1; min-width: 220px; max-width: 300px; text-align: center;"&gt;
    &lt;h4 style="color: #c62828;"&gt;Most Different (${mostDifferent.similarity}%)&lt;/h4&gt;
    &lt;img src="data/${mostDifferent.cover}" alt="${mostDifferent.album}" style="width: 100%; border-radius: 8px; box-shadow: 0 4px 6px rgba(0,0,0,0.1);"&gt;
    &lt;p style="margin-top: 8px; font-weight: bold; margin-bottom: 2px;"&gt;${mostDifferent.album}&lt;/p&gt;
    &lt;p style="color: #666; margin-top: 0;"&gt;${mostDifferent.artist}&lt;/p&gt;
  &lt;/div&gt;
&lt;/div&gt;
`}
`
